open Hedge.Router
open MobileHttp.Codecs

// The decoded-argument delegates for each endpoint, bound by Composition.bind over the
// module's Services. No Server.Env dependency: the host supplies behaviour via Services.
type Handlers = {
    signout: unit -> WorkerRequest -> ExecutionContext -> JS.Promise<WorkerResponse>
    exchange: MobileHttp.Api.Exchange.Request -> WorkerRequest -> ExecutionContext -> JS.Promise<WorkerResponse>
    me: unit -> WorkerRequest -> ExecutionContext -> JS.Promise<WorkerResponse>
    bootstrap: unit -> WorkerRequest -> ExecutionContext -> JS.Promise<WorkerResponse>
}

let dispatch (handlers: Handlers) (request: WorkerRequest) (ctx: ExecutionContext)
    : JS.Promise<WorkerResponse> option =
    let route = parseRoute request
    match route with
    | GET path when matchPath "/api/mobile/me" path = Some (Exact "/api/mobile/me") ->
        Some (handlers.me () request ctx)

    | POST path when matchPath "/api/mobile/exchange" path = Some (Exact "/api/mobile/exchange") ->
        Some (promise {
            let! bodyText = request.text()
            match Decode.fromString Decode.mobileHttpExchangeReq bodyText with
            | Error err -> return badRequest err
            | Ok req ->
                return! handlers.exchange req request ctx
        })

    | POST path when matchPath "/api/mobile/signout" path = Some (Exact "/api/mobile/signout") ->
        Some (handlers.signout () request ctx)

    | POST path when matchPath "/api/mobile/bootstrap" path = Some (Exact "/api/mobile/bootstrap") ->
        Some (handlers.bootstrap () request ctx)

    | _ -> None
